function passive2(slug, name, level, max, mods, extra = {}) {
  return {
    id: id2(slug),
    name,
    description: descriptions[slug] ?? name,
    job: "thief",
    specialization: null,
    tier: "core",
    tree: THIEF_TREE,
    unlockLevel: level,
    maxLevel: max,
    rankModifiers: Array.from({ length: max }, (_, i) => mods(i + 1)),
    ...extra
  };
}
