  if (palette) addArunikaSurfaceUv(flowerGeo);
  const flowers = new InstancedMesh(flowerGeo, palette?.get("flower_foliage") ?? createBasicMapMaterial("sand", { color: "#f1dfa2" }), Math.floor(grassPoints.length / 5));
