  const wheelTargetHeight = CAMERA_ZOOM.farTargetHeight + (CAMERA_ZOOM.nearTargetHeight - CAMERA_ZOOM.farTargetHeight) * wheelT;
  const wheelPitchOffset = CAMERA_ZOOM.farPitchOffset + (CAMERA_ZOOM.nearPitchOffset - CAMERA_ZOOM.farPitchOffset) * wheelT;
  let distance = wheelDistance;
  let targetHeight = wheelTargetHeight;
  let pitchOffset = state2.manualOrbitPitchLocked ? state2.manualOrbitPitchOffset : wheelPitchOffset;
  let manualOrbitPitchOffset = state2.manualOrbitPitchOffset;
  let manualOrbitPitchLocked = state2.manualOrbitPitchLocked;
  if (state2.manualOrbitPitchLocked) {
    const nearPivotBlend = smoothstep2(
      Math.max(0, Math.min(
        1,
        (12 - wheelDistance) / (12 - 3.5)
      ))
    );
    targetHeight = CAMERA_ZOOM.farTargetHeight + (CAMERA_ZOOM.nearTargetHeight - CAMERA_ZOOM.farTargetHeight) * nearPivotBlend;
    pitchOffset += -0.1 * nearPivotBlend;
  }
  if (state2.rmbFramingActive) {
    const stageOne = Math.min(1, rmbFraming / 0.55);
    const closeProgress = Math.max(0, (rmbFraming - 0.55) / 0.45);
    const stageT = smoothstep2(stageOne);
    const closeT = smoothstep2(closeProgress);
    const closeDistanceT = smoothstep2(closeT);
    const desiredDistance = CAMERA_ZOOM.max + (CAMERA_ZOOM.min - CAMERA_ZOOM.max) * closeDistanceT;
    distance = state2.distance + (desiredDistance - state2.distance) * rmbAlpha;
    targetHeight = wheelTargetHeight + (CAMERA_ZOOM.nearTargetHeight - wheelTargetHeight) * closeT;
    const groundPitch = -0.4;
    pitchOffset = stageOne < 1 ? CAMERA_ZOOM.farPitchOffset + (groundPitch - CAMERA_ZOOM.farPitchOffset) * stageT : groundPitch + (CAMERA_ZOOM.nearPitchOffset - groundPitch) * closeT;
    manualOrbitPitchOffset = pitchOffset;
    manualOrbitPitchLocked = true;
  }
  if (state2.rmbFramingActive) {
    targetHeight = state2.targetHeight + (targetHeight - state2.targetHeight) * rmbAlpha;
    pitchOffset = state2.pitchOffset + (pitchOffset - state2.pitchOffset) * rmbAlpha;
  }
